.dropdown {
  position: relative;
}

.header-menu .menu-list li a {
  transform: translate(-53px,1px);
}


.submenu {
  position: absolute;
  top: 20%;
  left: calc(55% + 53px); /* compensa o translate do link */
  background-color: #fff;
  border: 1px solid #ccc;
  border-radius: 6px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
  width: 200px;
  //padding: 0.5rem 0;
  z-index: 9999;
  padding-left: 65px
}


.submenu li {
  padding: 0;
}

.submenu li a {
  display: block;
  color: #01116F;
  padding: 8px 12px;
  text-decoration: none;
}

.submenu li a:hover {
  background-color: #f5f5f5;
}

#subMenuArrow,
.arrowFinanca {
  padding: 2px;
  color: #101A5C;
}

/* REGRA PADRÃO (Seta Branca no Hover) */
/* Este seletor (com a classe do pai e o :hover) é mais específico que a cor padrão. */
.tesouroHeaderlink:hover #subMenuArrow,
.tesouroHeaderlink:hover .arrowFinanca {
    color: white; /* Cor branca, sem !important */
}


.submenu3 {
 position: absolute;
 // top: 20%;
  //left: calc(55% + 53px); /* compensa o translate do link */
  transform: translateX(-47px);
  background-color: #fff;
  border: 1px solid #ccc;
  border-radius: 6px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
  width: 200px;
  //padding: 0.5rem 0;
  z-index: 9999;
   padding: 0.5rem 0;
  padding-left: 65px;

}

.submenu3 {
  list-style: none;  /* remove bullets */
  padding: 0;
  margin: 0;
  margin-left: -10px;
}

.submenu3 li a {
  display: block;          /* ocupa todo o li */
  width: 100%;
  padding: 0.5em 1em;     /* área clicável grande */
  text-decoration: none;
  color: inherit;
  box-sizing: border-box;
  transform: none !important; /* anula o transform herdado */
}

.submenu3 li a:hover {
  background-color: #01116F;
  color: #fff;
}
.submenu {
  list-style: none;
  padding: 0;
  margin: 0;
  background-color: #fff;
  border: 1px solid #ccc;
  border-radius: 6px;
  width: 220px; /* ajuste conforme necessário */
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}

.submenu li {
  /* garante que o <li> não adicione padding extra */
  padding: 0;
}

.submenu li a.submenu-link {
  display: block;          /* ocupa toda a li */
  width: 100%;
  padding: 0.5em 1em;      /* área clicável grande */
  text-decoration: none;
  color: #01116F;          /* cor padrão do texto */
  box-sizing: border-box;
    transform: none !important; /* anula o transform herdado */
}

.submenu li a.submenu-link:hover {
  background-color: #01116F; /* hover fundo cinza */
  color: #fff;               /* hover texto branco */
}



/* ------------------------------------------------------------------ */
/* 1. COMPORTAMENTO PADRÃO (Se a classe .menu-link-high-contrast não estiver presente) */
/* Este é o seu hover original que não deve ser alterado. */
/* ------------------------------------------------------------------ */

.header-menu a:hover,
.dropdown2 li a:hover,
.submenu li a:hover,
.submenu3 li a:hover,
#aUnderline:hover {
    background-color: #01116F;
    color: #ffffff;
}

/* ------------------------------------------------------------------ */
/* 2. COMPORTAMENTO DE ALTO CONTRASTE (Com a classe .menu-link-high-contrast) */
/* ------------------------------------------------------------------ */

/* ESTADO NORMAL do CONTRASTE (Links com a classe)
   Fundo: branco | Texto: preto */
.menu-link-high-contrast {
    background-color: #ffffff !important; 
    color: #000000 !important;           
}

/* ESTADO HOVER do CONTRASTE (Links com a classe, no mouse over)
   Fundo: preto | Texto: branco */
.menu-link-high-contrast:hover {
    background-color: #000000 !important; 
    color: #ffffff !important;           
}


/* Estilo para o ícone, seguindo sua ideia original */
.high-contrast-icon {
    color: #000000 !important;
    /* Deixamos o background em branco pelo estilo do link/pai */
}

/* ------------------------------------------------------------------ */
/* ESTILOS DE ACESSIBILIDADE NO MODO DE ALTO CONTRASTE */
/* ------------------------------------------------------------------ */

/* 1. ESTADO NORMAL e HOVER (Estilo fixo de contraste sem hover visual) */
.high-contrast-accessibility .linkAccessibility,
.high-contrast-accessibility .linkAccessibility:hover, /* Aplicamos a mesma cor no hover */
.high-contrast-accessibility .linkAccessibility .accessibilityTexts,
.high-contrast-accessibility .linkAccessibility .accessibilityTexts:hover {

    /* Aplica o estilo de contraste aos links e textos (A, B, SPAN) */
    background-color: transparent !important;
    color: #fff !important;               /* Texto Branco */
   	text-decoration: none !important; 
}

/* 2. GARANTIA do SVG (Opcional, mas recomendado) */
/* Garante que o SVG (e seu conteúdo) não mude de cor e mantenha o 'currentColor'
   ou sua cor original no modo de alto contraste. */
.high-contrast-accessibility .linkAccessibility svg {
    /* Reseta qualquer mudança de cor que possa ter vindo de um seletor mais genérico */
    color: initial !important; 
    fill: currentColor; /* Ou a cor que o seu SVG deveria ter normalmente */
}

/* 3. Garante que o background do HOVER seja transparente para desativar o efeito */
.high-contrast-accessibility .linkAccessibility:hover {
    background-color: transparent !important;
}

/* ------------------------------------------------------------------ */
/* REGRAS PARA REMOVER BACKGROUNDS EM MODO DE CONTRASTE (CLAREZA)       */
/* ------------------------------------------------------------------ */

/* Aplica-se ao container principal do menu e acessibilidade */
.high-contrast, 
.high-contrast-accessibility {
    /* Garante que o container principal não tenha background */
    background-color: transparent !important;
}


/* ------------------------------------------------------------------ */
/* 2. COMPORTAMENTO DE ALTO CONTRASTE */
/* ------------------------------------------------------------------ */

/* ESTADO NORMAL do CONTRASTE (Links com a classe)
   Fundo: branco | Texto: preto */
.menu-link-high-contrast {
    background-color: #ffffff !important;
    /* Deixamos a cor do texto herdar do CSS normal ou ser forçada pelo JS */
    color: #000000 !important; /* Mantenha o texto preto no estado normal */
}

/* ESTADO HOVER do CONTRASTE (Links gerais do menu, EXCETO a seta)
   Fundo: preto | Cor: (Removemos a cor para herdar do JS ou CSS) */
.menu-link-high-contrast:hover {
    background-color: #000000 !important;
    /* REMOVEMOS: color: #ffffff !important; */ 
    /* Isso impede que o texto 'PRINCIPAIS SISTEMAS' mude para branco! */
    /* A cor dos OUTROS links do menu (Tesouro, Painéis, etc.) vai herdar o #FFF, o que deve ser o desejado */
}

/* REGRA ESPECÍFICA PARA A SETA DENTRO DO LINK HOVER */
/* Apenas quando o link pai está em hover, o ID da seta muda a cor para branco. */
.tesouroHeaderlink:hover #idArrowPrincipais {
    color: #ffffff !important; /* Seta fica BRANCA no hover */
    background-color: transparent !important; /* Garantimos que não tenha fundo */
}



/* ------------------------------------------------------------------ */
/* MEDIA QUERIES PARA RESPONSIVIDADE DO MENU */
/* ------------------------------------------------------------------ */

/* 1. Breakpoint para Telas Médias (Ex: Tablets em modo Paisagem - Max-width: 992px) */
@media (max-width: 992px) {
    /* 1. Garante que o link volte para a posição normal e tenha fonte menor */
    .header-menu .menu-list li a {
        font-size: 1.2rem !important;
        padding: 5px 10px;
        transform: none !important; /* ZERA O TRANSLATE DE -53PX/OUTROS */
    }

    /* 2. Remove o afastamento residual (gap) */
    .header-menu .menu-list {
        gap: 0.5em; /* Reduz o espaçamento entre itens se 1em for muito */
        padding-left: 10px; /* Ajusta a margem esquerda da lista se necessário */
    }

    /* 3. Se o tesouroHeaderlink estiver com espaçamento ruim */
    .tesouroHeaderlink {
        padding: 5px 10px;
        font-size: 0.9rem;
    }

    /* 4. Ajuste específico para o Tesouro Estadual */
    #tesouroPointer {
        transform: none !important; /* Zera qualquer transform específico */
        font-size: 1.2rem !important; /* Garante que a fonte seja a correta */

    }

  /* 1. DIMINUI O TAMANHO DO ÍCONE */
    #idhamb2 {
        font-size: 1.3rem !important; /* Diminui de 1.7rem para um tamanho menor */
        /* Ajuste o tamanho da fonte (1.3rem) conforme o que você deseja */
    }

    /* 2. ALINHA HORIZONTALMENTE */
    /* Você tem duas opções para o primeiro <li>: */

    /* OPÇÃO A: Ajustar o link (a) que envolve o ícone */
    .header-menu .menu-list li:first-child a[ng-if="!isHomePage"] {
        /* Puxa para a esquerda, anulando qualquer outro espaçamento. Ajuste o valor! */
        margin-left: -15px !important; 
        /* Zera o padding do container do ícone se ele estiver empurrando */
        padding-left: 0 !important; 
    }

    /* OPÇÃO B (se a A não funcionar): Ajustar o ícone diretamente */
    /* #idhamb2 {
        margin-left: -15px !important; 
    } */

    /* 3. ALINHA VERTICALMENTE (Opcional) */
    /* Se o ícone estiver muito alto ou baixo: */
    #idhamb2 {
        /* Se precisar de um ajuste vertical fino */
        transform: translateY(1px) !important; 
    }
}
/* 2. Breakpoint para Telas Pequenas (Ex: Tablets em modo Retrato e Celulares - Max-width: 768px) */
@media (max-width: 768px) {

    /* A maioria dos menus horizontais vira menu hamburguer ou se empilha neste ponto.
       Se seu menu é um hamburguer, este CSS é para o modo "expandido".
    */

    /* Configura a lista de menu para se empilhar verticalmente */
    .header-menu .menu-list {
        display: block; /* Volta para o comportamento de bloco (vertical) */
        width: 100%;    /* Ocupa a largura total do container */
        padding: 0;
        margin: 0;
        /* Se o menu-list é flex ou grid, mude para: flex-direction: column; */
    }

    /* Faz cada item de menu ocupar a largura total e garante o alinhamento */
    .header-menu .menu-list li {
        display: block;
        border-bottom: 1px solid #eee; /* Linha de separação entre itens */
    }

    /* Ajusta os links para ocupar 100% do espaço horizontal e ser mais legível */
    .header-menu .menu-list li a,
    .tesouroHeaderlink,
    #aUnderline {
        display: block;
        width: 100%;
        padding: 10px 15px; /* Mais padding para facilitar o toque */
        text-align: left;
        transform: none !important; /* Limpa qualquer transformação */
    }

    /* Garante que os submenus apareçam abaixo do item pai e ocupem 100% da largura */
    .dropdown2,
    .submenu,
    .submenu3 {
        position: static; /* Impede que o submenu flutue/ocupe posição absoluta */
        width: 100%;      /* Ocupa a largura total */
        border: none;
        border-top: 1px solid #ccc;
        box-shadow: none;
        padding-left: 15px; /* Adiciona um recuo para diferenciar */
        background-color: #f8f8f8; /* Mude a cor do fundo para diferenciar */
    }

    /* Ajusta o padding interno dos submenus */
    .submenu li a,
    .submenu3 li a {
        padding-left: 20px; /* Recuo extra para sub-itens */
    }

    /* Ajusta o ícone de 'home/bars' para ficar no canto */
    .header-menu .menu-list li:first-child {
        /* Ajuste a visibilidade e posição do ícone se ele for usado como botão de menu-hamburguer */
        display: block;
    }

    /* Oculta a seta de submenus no modo mobile (opcional) */
    .fa-arrow-right {
        float: right; /* Move a seta para a direita */
    }

   .hambIcon {
        display: none !important; 
    }

    /* 2. Oculta o container de busca */
    .search-wrapper {
        display: none !important;
    }

    /* Nota: Se o <li> pai do ícone hambúrguer (o primeiro <li>) precisar ser removido 
       para evitar um espaço vazio, adicione a regra abaixo.
       Se você já tem outros <a> no primeiro <li>, use uma regra mais específica.
       Abaixo, estou ocultando o <li> que contém o ícone hamburguer:
    */
    .menu-list > li:first-child {
        display: none !important;
    }
   #tesouroPointer {
         /* Reduz o padding interno do link 'TESOURO ESTADUAL' */
         padding-left: 5px;
         padding-right: 5px;
      font-size: 0.9rem;
    }

}

#idhamb2{
		position: relative;
    font-size: 1.6rem;
    // margin-right: 1rem;
    cursor: pointer;
    color: #01116F;
    transform: translate(49px, 2px);
}
/* ------------------------------------------------------------------ */
/* MEDIA QUERY PARA AJUSTE DE ALINHAMENTO (821px a 912px) */
/* Objetivo: Puxar o menu e seus itens mais para a esquerda. */
/* ------------------------------------------------------------------ */
@media (min-width: 821px) and (max-width: 912px) {

    /* 1. Ajuste no Container Principal do Menu (opcional)
       Se o menu estiver centralizado ou com margem automática, isso pode ajudar a empurrá-lo. */
    .header-menu {
        /* Reduz a margem esquerda ou adiciona padding negativo se necessário */
        padding-left: 0; 
        margin-left: 0;
    }

    /* 2. Ajuste na Lista de Itens (UL)
       Usamos margem negativa para puxar a lista mais para a esquerda. */
    .header-menu .menu-list {
        /* Puxa a lista inteira para a esquerda. Ajuste o valor se precisar de mais. */
        margin-left: -5px; 
    }

    /* 3. Ajuste nos Links Individuais
       O seu CSS base tinha um transform: translate(-53px,1px);
       Vamos ajustar esse valor para os links, EXCETO o primeiro (ícone).
    */
    .header-menu .menu-list li a {
        /* Ajuste o valor X (horizontal) para um número menor (mais perto da esquerda/origem)
           Exemplo: De -53px para -60px. Ajuste conforme sua necessidade visual.
           O valor de 53px na sua regra original já está puxando para a esquerda (-53px). 
           Se você quer "puxar mais para a esquerda", precisa de um valor MAIS NEGATIVO.
           Se você quer "trazer de volta para a direita", precisa de um valor MENOS NEGATIVO.

           Se o texto do Tesouro Estadual (que é maior) está empurrando os outros para a direita:
        */

        /* Tenta reajustar o translate para dar mais espaço, ou desativá-lo */
        transform: translate(-60px, 1px); /* Exemplo: Puxa 7px a mais para a esquerda */

        /* Outra opção é ajustar o padding, se o transform estiver complicado: */
        padding-left: 5px; 
        padding-right: 5px; /* Reduz o padding para juntar os itens */
    }

    /* 4. Especificidade para o Link Tesouro Estadual (se precisar)
       Se 'TESOURO ESTADUAL' está grande e empurrando, garanta que ele tenha menos padding/margem. */
    #tesouroPointer {
         /* Reduz o padding interno do link 'TESOURO ESTADUAL' */
         padding-left: 5px;
         padding-right: 5px;
      	font-size: 0.9rem;
    }
}
@media (max-width: 820px) {
	#tesouroPointer {
         /* Reduz o padding interno do link 'TESOURO ESTADUAL' */
         //padding-left: 5px;
         //padding-right: 5px;
         font-size: 0.9rem;
    }
}

@media (min-width: 769px) and (max-width: 820px) {
 .header-menu .menu-list {
        gap: 0.5em;
    }
  #iconHamb{
  	font-size: 1.5rem;
    transform: translateX(-16px);
  }
  .dropdown {
  	margin-right: 0;
  }
  .tesouroHeaderlink{
  	//gap:20px;
  }
  #idArrowPrincipais{
  	margin-right: 27px;
  }
   .search-wrapper {
