    }

}

@media (min-width: 821px) and (max-width: 960px) {
  #iconHamb{
  	transform: translateY(0px);
    margin-right: 15px;
    font-size: 12px;
  }
  #tesouroPointer{
  	transform: translate(-43px, 1px);
    font-size: .9rem;

  }
     .search-wrapper {
        display: none !important;
    }
}

@media (max-width: 768px) {
    /* 1. **CRUCIAL:** Força o container principal a empilhar seus filhos (lista de links e container de busca) */
    .header-menu {
        display: flex !important; /* Mantém o display: flex */
        flex-direction: column !important; /* Força a coluna: busca abaixo da lista */
        align-items: center !important; /* Centraliza a coluna se quiser */
        width: 100%;
        min-height: auto; /* Permite que a altura se ajuste ao conteúdo */
        overflow-x: hidden; /* Evita a barra de rolagem horizontal */
    }

    /* 2. Garante que a lista de menu ocupe a largura total para mobile */
    .header-menu .menu-list {
        display: block !important; /* Ou use flex-direction: column */
        width: 100% !important;
        /* Mantenha seu padding: 0; margin: 0; */
    }

    /* 3. Garante que o container da busca ocupe a largura total */
    .header-container {
        width: 100% !important;
        padding: 0;
        margin-top: 5px; /* Adiciona um espaço para separar da lista de links */
    }

    /* 4. Garante que o .row empilhe ou se comporte como bloco */
    .header-container .row {
        flex-direction: column !important; /* Mantém a regra de empilhamento interna */
        display: block !important; /* Garante que o row não force layout horizontal */
        width: 100% !important;
        padding: 0 15px !important;
    }

    /* 5. Garante que o search-wrapper seja exibido e ocupe o espaço */
    .search-wrapper {
        display: block !important;
        width: 100% !important;
        padding-right: 0 !important; /* Remove o padding-right que pode estar puxando */
        /* Remova ou zere o display: none */
    }
  #tesouroPointer {
  padding-left: 1.5rem;
  }
}
@media (max-width: 430px) {
		.accessibility {
    display: flex;
    gap: 1em;
    color: #FFF;
    justify-content: center;
    align-items: center;
    font-size: 10px;

	}

  .user-initials {
   width: 28px; /* NOVO: Reduz a largura */
   height: 28px; /* NOVO: Reduz a altura (mantém o círculo) */
   font-size: 10px;
  }

}
/* --- Responsividade do Widget de Busca --- */

/* 1. Para telas grandes (ex: 993px - 1200px) */
/* Mantém o padrão, mas reduz um pouco se 400px for muito. */
@media (min-width: 993px) and (max-width: 1200px) {
    .search-widget {
        max-width: 350px; /* Reduz a largura máxima do widget */
    }
}

/* 2. Para tablets (ex: 769px - 992px) */
@media (min-width: 769px) and (max-width: 992px) {
    .search-widget {
        max-width: 300px; /* Reduz mais a largura */
    }
}

/* 3. Para tablets/celulares grandes (ex: 541px - 768px) */
/* Nesta faixa, é comum deixar a busca com uma largura maior ou total, mas com um padding. */
@media (min-width: 541px) and (max-width: 768px) {
    .search-widget {
        max-width: 90%; /* Ocupa 90% da largura do container pai */
    }
    .search-wrapper {
        justify-content: center; /* Centraliza a caixa de busca */
    }
}

/* 4. Para celulares (ex: max-width: 540px) */
/* Aqui, a busca geralmente ocupa a largura total para facilitar o uso. */
@media (max-width: 540px) {
    .search-widget {
        max-width: 100%; /* Ocupa 100% da largura, dentro do padding do container */
    }
    /* O padding deve ser aplicado no .search-wrapper para dar margem nas laterais */
    .search-wrapper {
        padding: 10px 15px !important; 
        box-sizing: border-box;
    }
}

